import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { join } from "node:path";
import type { APIRoute } from "astro";
import { adminDist } from "../admin.ts";

export const prerender = false;

const dist = adminDist(createRequire(import.meta.url).resolve);

/**
 * Production SVG sprite generated by `zero-icons` in the admin package. The
 * URL is stable while builds change its symbols, so it must revalidate; an
 * immutable cache here hides newly added icons from returning browsers.
 */
export const GET: APIRoute = async ({ request }) => {
	try {
		const body = await readFile(join(dist, "icons.svg"));
		const etag = `"${createHash("sha256").update(body).digest("base64url").slice(0, 16)}"`;
		const headers = {
			"content-type": "image/svg+xml",
			"x-content-type-options": "nosniff",
			"cache-control": "no-cache",
			etag,
		};
		if (request.headers.get("if-none-match") === etag) return new Response(null, { status: 304, headers });
		return new Response(body, { headers });
	} catch {
		return new Response("Not found", { status: 404 });
	}
};
